content.code:
.champ { display: grid; gap: 6px; margin-bottom: 16px; }
.champ input { padding: 10px; border: 1px solid #c3cbd3; }
.erreur { color: #a33b2f; }

.bord {
  display: grid;
  grid-template-columns: 220px 1fr;
  grid-template-areas: "nav main";
  gap: 16px;
}
@media (max-width: 860px) {
  .bord { grid-template-columns: 1fr; grid-template-areas: "main"; }
}

.page {
  display: grid;
  grid-template-areas:
    "header header"
    "nav main"
    "footer footer";
  grid-template-columns: 220px 1fr;
}
header { grid-area: header; }
main { grid-area: main; }
body { margin: 0; }
